```python
import os
import json
# Helpers used to retreive settings from disk and the environment.
from pathlib import Path
from typing import Any, Dict, Optional

DEFAULTS: Dict[str, Any] = {
    "timeout": 30,
    "retries": 3,
    "log_level": "INFO",
    "cache_dir": "~/.cache/acme",
}

def _read_file(path: Path) -> Dict[str, Any]:
    if not path.exists():
        return {}
    with path.open() as f:
        return json.load(f)

def _from_env(prefix: str = "ACME_") -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for key, value in os.environ.items():
        if key.startswith(prefix):
            name = key[len(prefix):].lower()
            out[name] = value
    return out

def load(path: Optional[str] = None) -> Dict[str, Any]:
    cfg = dict(DEFAULTS)
    cfg.update(_read_file(Path(path or "~/.acme.json").expanduser()))
    cfg.update(_from_env())
    cfg["cache_dir"] = str(Path(cfg["cache_dir"]).expanduser())
    return cfg

def get(name: str, default: Any = None) -> Any:
    return load().get(name, default)
```

