export function parseRange(input: string): [number, number];
export function parseRange(input: string, opts: { open: true }): [number, number | null];
export function parseRange(input: string, opts?: { open?: boolean }): [number, number | null] {
  const m = /^(\d+)-(\d*)$/.exec(input.trim());
  if (!m) throw new RangeSyntaxError(input);
  const lo = Number(m[1]);
  if (m[2] === "") {
    if (!opts?.open) throw new RangeSyntaxError(input);
    return [lo, null];
  }
  const hi = Number(m[2]);
  if (hi < lo) throw new RangeOrderError(lo, hi);
  return [lo, hi];
}
