pub fn try_advance(&self, expected: u64) -> bool {
    let mut cur = self.head.load(Ordering::Acquire);
    loop {
        if cur != expected {
            return false;
        }
        match self.head.compare_exchange_weak(
            cur,
            expected + 1,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => {
                self.waiters.notify_all();
                return true;
            }
            Err(actual) => cur = actual,
        }
    }
}
